import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Combinator presentation of the IR (monoidal + trace)","description":"","frontmatter":{"title":"Combinator presentation of the IR (monoidal + trace)","type":"adr","date":"2026-10-14T00:00:00.000Z","status":"proposed"},"headers":[],"relativePath":"graphopt/project/adrs/0008-combinator-presentation.md","filePath":"vendored/graphopt/project/adrs/0008-combinator-presentation.md"}`),a={name:`graphopt/project/adrs/0008-combinator-presentation.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0008-—-combinator-presentation-of-the-ir-monoidal-trace" tabindex="-1">ADR 0008 — Combinator presentation of the IR (monoidal + trace) <a class="header-anchor" href="#adr-0008-—-combinator-presentation-of-the-ir-monoidal-trace" aria-label="Permalink to “ADR 0008 — Combinator presentation of the IR (monoidal + trace)”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>Add a combinator presentation layer over the IR — parallel, not a replacement.</strong> The op-graph IR stays the lowering surface (sinks, executors, <code>pack</code>); the combinator presentation is the <em>discovery and semantics</em> surface.</p><h3 id="the-presentation" tabindex="-1">The presentation <a class="header-anchor" href="#the-presentation" aria-label="Permalink to “The presentation”">​</a></h3><ul><li>Terms are morphisms of a symmetric monoidal category with Δ (sharing is a morphism, not a pointer convention) plus <code>loop</code> (typed trace — state shape fixed).</li><li>A bridge, both directions: <code>dag → combinator</code> (fan-out becomes explicit <code>Δ</code>; <code>pack</code> becomes <code>⊗</code>) and <code>combinator → dag</code> (lower via expansion of structure morphisms).</li><li>Laws remain equations — now between combinator expressions. The same admission gauntlet applies (ADR 0004/0007): oracle → typed gate → certificate → adversarial sweep → measured pay.</li></ul><h3 id="what-becomes-definable-the-payoff" tabindex="-1">What becomes definable (the payoff) <a class="header-anchor" href="#what-becomes-definable-the-payoff" aria-label="Permalink to “What becomes definable (the payoff)”">​</a></h3><ul><li><strong>Carrier atoms as <code>loop</code> instances.</strong> <code>applyd</code>/<code>om_decayed</code>/ <code>decay_vec</code> cease to be primitives — the RetNet carrier is a spelled trace term. The authored-atom problem dissolves.</li><li><strong>Weight-space laws as ordinary rewrites.</strong> Params as morphisms → conv+BN folding, reparameterization, linear-chain folding are equations in the same object language as everything else.</li><li><strong>Sharing as structure.</strong> <code>Δ</code> makes fan-out explicit — the DAG-vs-tree ambiguity class of bugs is impossible by construction.</li><li><strong>A uniform discovery space.</strong> Proposers enumerate morphism shapes of the free category — naturality/factorization families stop being separately-coded generators.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The recurring user question this week — <em>&quot;why is X hardcoded?&quot;</em> — has a single root: <strong>the object language is an op-graph, so anything that isn&#39;t an op-node needs a hand-minted atom.</strong> Carrier atoms (<code>om_decayed</code>, <code>applyd</code>, <code>decay_vec</code>, <code>aff_diag</code>) are authored primitives; multi-output needed a bespoke <code>pack</code>; sharing is implicit in the DAG and has bitten us (the inf-norm sharing divergence); weight-space rewrites need a new law family because parameters are leaves, not morphisms. ADR-0007 retires part of this by minting atoms mechanically — but minted atoms are still <em>atoms</em>: the object language has no combinator structure of its own.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>The authored atom set shrinks to the combinator basis</strong> — the</li><li><strong>Discovery targets morphisms, not op-tuples</strong> — proposer</li><li><strong>A runtime is a diagram family.</strong> The ADR-0007 emergent-runtime</li><li><strong>Both surfaces coexist deliberately</strong> — the op-graph stays for</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0008-combinator-presentation.html"><code>design/0008-combinator-presentation.md</code></a>.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};